training.use=r=>{document.querySelector('[data-mode="training"]').click();trainPicker.set(r);const id=$('train-node').value;$('train-from').value=window.MasteryUI.levels()[id]||0;training.render()};

const shipping=view('shipping',`<section class="panel"><div class="section-heading"><h2>Соберите товары в один план</h2><button id="ship-from-craft" class="button primary">Добавить текущую партию крафта</button></div><p class="hint">Еда и зелья распределяются между Bridgewatch, Fort Sterling, Lymhurst, Martlock и Thetford. Карлион используется только для чёрного рынка вещей, сумок и PvE-лута.</p><details class="fold"><summary>Добавить предмет вручную или PvE-лут</summary><div class="fold-body">${picker('ship')}<div class="grid2">${number('Количество','ship-add-qty',100,'step="1"')}${select('Город отправления','ship-add-origin',SM.safeCities.concat('Caerleon').map(c=>opt(c)).join(''))}</div>${select('Куда продавать','ship-add-destination',opt('safe','Распределить по безопасным городам')+opt('blackMarket','Карлион · чёрный рынок'))}${select('Качество предмета','ship-add-quality',[1,2,3,4,5].map((q,i)=>opt(q,['Обычное','Хорошее','Выдающееся','Отличное','Шедевр'][i])).join(''))}${number('Закупка / себестоимость за штуку','ship-add-cost','','step="0.01" placeholder="Цена предмета; 0 для добытого лута"')}<p class="hint">Для добытого PvE-лута можно указать 0. Для купленных вещей укажите закупку. При пустой цене прибыль не рассчитывается.</p><button id="ship-add" class="button">Добавить в план</button><p id="ship-add-status" class="hint" role="status"></p></div></details></section><section class="panel"><h2>Партии товаров</h2><div id="ship-items"></div><p id="ship-empty" class="hint">Добавьте партию из крафта или выберите лут вручную.</p></section><section class="panel"><h2>Настройки распределения</h2><div id="ship-enabled" class="city-toggles">${SM.safeCities.map(c=>`<label><input type="checkbox" data-ship-enabled="${c}" checked> ${c}</label>`).join('')}</div><div class="grid2">${number('Налог продажи, %','ship-tax',4,'max="100" step="0.1"')}${number('Постановка ордера, %','ship-setup',2.5,'max="100" step="0.1"')}</div><label class="switch"><input id="ship-profitable" type="checkbox" checked> На чёрный рынок — только позиции с положительной прибылью</label><p class="hint">Обычные города: ордер продажи. Чёрный рынок: мгновенная продажа по ордеру покупки, без платы за постановку. Доли считаются отдельно для каждого предмета и качества по средним продажам за 14 завершённых дней. Доля нормируется между выбранными городами с подтверждённой ценой и историей; города без данных не получают товар. Это наблюдаемый оборот рынка; сроки продажи вашей партии могут отличаться.</p><p id="ship-market-status" role="status" class="hint"></p><button id="ship-export" class="button">Скачать план перевозок CSV</button></section><div class="activity-summary" id="ship-summary"></div><section class="panel"><h2>Сколько отвезти в каждый город</h2><div id="ship-chart"></div><div id="ship-excluded" class="hint" role="status"></div><div class="table-scroll"><table><thead><tr><th>Предмет</th><th>Маршрут</th><th>Доля продаж</th><th>Отвезти</th><th>Цена / шт.</th><th>Чистая прибыль</th><th>Дней общего оборота</th></tr></thead><tbody id="ship-plan"></tbody></table></div></section><section class="panel"><h2>Рейсы и расходы на дорогу</h2><p class="hint">Расход задаётся один раз на маршрут для всех его товаров. Если потребуется несколько рейсов, укажите их суммарную стоимость. Для Карлиона показан отдельный маршрут к чёрному рынку.</p><div id="ship-routes"></div></section><section class="panel"><h2>Прибыль по маршрутам</h2><div id="ship-profit-chart"></div></section>`);
window.ActivityViews.shipping=shipping;let shipState={items:[],enabled:{},routeCosts:{},tax:4,setup:2.5,profitableOnly:true,manual:{}};try{shipState={...shipState,...JSON.parse(localStorage.getItem('albion-shipping-v1')||'{}')}}catch{}let shipResult,shipPicker;
